def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if not alive_opponents:
        base = 18.0 if hp > 3 else 40.0
        return max(0.0, min(float(budget), base))

    prev_bids = []
    desperate_count = 0
    rich_count = 0
    for opp in alive_opponents:
        if opp.get('hp', 10) <= 2 or opp.get('no_water_days', 0) >= 1:
            desperate_count += 1
        if opp.get('budget', 0) >= budget:
            rich_count += 1
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            prev_bids.append(float(prev['bid']))
            if prev.get('status') == 'won':
                prev_bids.append(float(prev['bid']) + 0.5)

    if hp <= 1:
        target = DAILY_SALARY * 0.98
        if prev_bids:
            target = max(target, min(float(budget), max(prev_bids) + 2.0))
        return max(0.0, min(float(budget), target))

    if hp <= 2 or no_water_days >= 1:
        target = DAILY_SALARY * 0.82
        if prev_bids:
            target = max(target, max(prev_bids) + 1.5)
        if supply >= 22:
            target -= 6.0
        return max(0.0, min(float(budget), target))

    pressure = 0.0
    if prev_bids:
        highest_prev = max(prev_bids)
        avg_prev = sum(prev_bids) / len(prev_bids)
        pressure = max(highest_prev * 0.75, avg_prev)
    else:
        pressure = DAILY_SALARY * 0.45

    if supply >= 22:
        base = 24.0
    elif supply >= 18:
        base = 31.0
    else:
        base = 39.0

    if desperate_count > 0:
        base += 8.0
    if rich_count >= len(alive_opponents) / 2.0:
        base += 4.0
    if day >= 8:
        base += 6.0

    if prev_bids:
        highest_prev = max(prev_bids)
        if highest_prev >= DAILY_SALARY * 0.9 and hp > 3 and no_water_days == 0:
            bid = base * 0.8
        else:
            bid = max(base, min(highest_prev + 1.0, pressure + 3.0))
    else:
        bid = base

    if budget < DAILY_SALARY * 0.6 and hp > 2:
        bid = min(bid, DAILY_SALARY * 0.45)

    return max(0.0, min(float(budget), float(bid)))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 1)

    hp = float(my_status.get('hp', 0))
    budget = float(my_status.get('budget', 0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for opp in opponents_status.values():
        if opp.get('alive', False):
            alive_opps.append(opp)

    # If no opponents, take what you can afford but avoid overpaying.
    if not alive_opps:
        target = min(budget, DAILY_SALARY * 0.45)
        return max(0.0, float(target))

    # Read yesterday bids from opponents' previous_trace.
    prev_bids = []
    for opp in alive_opps:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            try:
                prev_bids.append(float(prev.get('bid')))
            except Exception:
                pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0

    # Determine how many WATER_REQ units supply can likely support.
    # Use explicit int() on any index-like operations; here we only compute counts.
    # Heuristic: aim to win 1 unit when supply is in [15,25].
    expected_units = int(supply / float(WATER_REQ)) if WATER_REQ > 0 else 0
    if expected_units < 1:
        expected_units = 1

    # Urgency: if low hp or already many no-water days, bid more aggressively.
    urgency = 0.0
    if hp <= 2.0:
        urgency += 0.35
    elif hp <= 4.0:
        urgency += 0.2
    if no_water_days >= 2:
        urgency += 0.25
    elif no_water_days >= 1:
        urgency += 0.1

    # Base bid level: fraction of daily salary scaled by expected units.
    # In medium scenario supply 15-25 => expected_units is 1 or 2.
    base_frac = 0.55
    if expected_units >= 2:
        base_frac = 0.45
    base_frac = base_frac + urgency

    # If opponents were bidding very high yesterday, avoid direct chase; counter slightly below peak.
    if highest_prev_bid > 0.0:
        if highest_prev_bid >= DAILY_SALARY * 0.85:
            # Price war likely; bid just enough to compete.
            bid = min(budget, highest_prev_bid * 0.92)
        else:
            # Moderate competition; bid around base but ensure it beats typical bids.
            bid = max(base_frac * DAILY_SALARY, highest_prev_bid * 0.98)
    else:
        bid = base_frac * DAILY_SALARY

    # If my hp is extremely low, increase to near desperation.
    if hp <= 1.5:
        bid = max(bid, DAILY_SALARY * 0.85)

    # Cap by budget and keep non-negative.
    bid = float(bid)
    if bid < 0.0:
        bid = 0.0
    if bid > budget:
        bid = budget

    return bid
